import os, re, fitz
Pdef find_references_start(doc: fitz.Document):
    for i, page in enumerate(doc):
        txt = page.get_text().lower()
        if re.search(r'(?m)^\s*(?:\d+\s*\.?\s*)?references\b', txt):
            return i
    for i, page in enumerate(doc):
        if re.search(r'\breferences\b', page.get_text().lower()):
            return i
    return None
def refs_heading_y(page: fitz.Page):
    # find y position of the first REFERENCES heading-like match
    rects = page.search_for('References') + page.search_for('REFERENCES')
    if not rects:
        # sometimes numbered like "4. References"
        rects = page.search_for('References')
    if not rects:
        return None
    return min(r.y0 for r in rects)
def collect_patterns(doc: fitz.Document, refs_page: int|None):
    max_page = (refs_page if refs_page is not None else len(doc))
    patterns=set()
    def add(p):
        p=(p or '').strip()
        if len(p)>=6:
            patterns.add(p)
    # metadata authors (full names)
    author_meta = (doc.metadata.get('author') or '').strip()
    if author_meta:
        for part in re.split(r'[;,]\s*', author_meta):
            add(part)
    subj=(doc.metadata.get('subject') or '').strip()
    if subj:
        add(subj)
    url_re=re.compile(r'https?://\S+')
    email_re=re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
    arxiv_re=re.compile(r'(arXiv\s*:\s*\d{4}\.\d{4,5}(?:v\d+)?)', re.I)
    arxiv_url_re=re.compile(r'https?://arxiv\.org/abs/\S+', re.I)
    # slightly safer DOI redaction: only if it appears outside references AND is preceded by DOI label
    doi_re=re.compile(r'(?:doi\s*:\s*|https?://doi\.org/)(10\.\d{4,9}/[-._;()/:A-Za-z0-9]+)', re.I)
    # scan pages before references
    for pi in range(max_page):
        page=doc[pi]
        text=page.get_text()
        for m in email_re.findall(text):
            add(m)
        for m in arxiv_re.findall(text):
            add(m)
        for m in arxiv_url_re.findall(text):
            add(m.rstrip(').,;]'))
        for m in doi_re.findall(text):
            add(m)
        for m in url_re.findall(text):
            add(m.rstrip(').,;]'))
        # collect affiliation-like lines from first page (including footnotes)
        if pi==0:
            for ln in [l.strip() for l in text.splitlines() if l.strip()]:
                if any(k in ln for k in ['University','Institute','Laboratory','College','School','Inc.','LLC','Corp','Company']):
                    # remove leading numeric markers like "1Duke"
                    ln2=re.sub(r'^\s*\d+\s*', '', ln)
                    ln2=re.sub(r'\b\d+(?=[A-Z])', '', ln2)
                    # split comma-separated
                    for seg in [s.strip() for s in re.split(r'\s*,\s*', ln2) if s.strip()]:
                        # keep the longer segments that look like affiliations / locations
                        if len(seg) >= 10:
                            add(seg)
    # author list heuristics on page 0: parse before Abstract
    first = doc[0].get_text()
    lines=[ln.strip() for ln in first.splitlines() if ln.strip()]
    abs_i=None
    for i,ln in enumerate(lines):
        if ln.lower()=='abstract' or ln.lower().startswith('abstract'):
            abs_i=i
            break
    header_lines=lines[:abs_i] if abs_i is not None else lines[:30]
    name_re=re.compile(r'\b([A-Z][A-Za-z\-\']+\s+[A-Z][A-Za-z\-\']+(?:\s+[A-Z][A-Za-z\-\']+)?)\b')
    for ln in header_lines:
        if ln.count(',')>=1 or '∗' in ln or '*' in ln or any(ch.isdigit() for ch in ln):
            # remove footnote markers & digits so we can capture names like "Shi1" -> "Shi"
            clean=re.sub(r'[^A-Za-z\s\-\']+', ' ', ln)
            clean=re.sub(r'\s+', ' ', clean).strip()
            for nm in name_re.findall(clean):
                # filter obvious non-names
                if nm.lower() in {'introduction','abstract'}:
                    continue
                if len(nm.split())>=2:
                    add(nm)
    # venue strings: redact full occurrences found on pages before references
    venue_markers=[
        'Proceedings of',
        'International Conference on',
        'Conference on',
        'Workshop on',
    ]
    for pi in range(max_page):
        txt=doc[pi].get_text()
        for ln in [l.strip() for l in txt.splitlines() if l.strip()]:
            if any(vm in ln for vm in venue_markers) and len(ln) >= 20:
                add(ln)
    return sorted(patterns, key=len, reverse=True)
def verify_redaction(original_path, output_path):
    orig = fitz.open(original_path)
    redc = fitz.open(output_path)
    orig_len = sum(len(p.get_text()) for p in orig)
    redc_len = sum(len(p.get_text()) for p in redc)
    print(f"Original: {len(orig)} pages, {orig_len} chars")
    print(f"Redacted: {len(redc)} pages, {redc_len} chars")
    print(f"Retained: {redc_len/orig_len:.1%}")
    if len(redc) != len(orig):
        raise ValueError(f"Page count changed: {len(orig)} -> {len(redc)}")
    if redc_len < 1000:
        raise ValueError(f"PDF corrupted: only {redc_len} chars remain!")
    if redc_len < orig_len * 0.7:
        raise ValueError(f"Too much removed: kept only {redc_len/orig_len:.0%}")
    orig.close(); redc.close()
    print('✓ Verification passed')
def redact_one(input_path, output_path):
    doc=fitz.open(input_path)
    refs_page=find_references_start(doc)
    patterns=collect_patterns(doc, refs_page)
    refs_y=None
    if refs_page is not None:
        refs_y=refs_heading_y(doc[refs_page])
    for pi in range(len(doc)):
        page=doc[pi]
        if refs_page is not None and pi > refs_page:
            continue
        clip_y=None
        if refs_page is not None and pi==refs_page and refs_y is not None:
            clip_y = refs_y - 2
        for pat in patterns:
            for r in page.search_for(pat):
                if clip_y is not None and r.y1 >= clip_y:
                    continue
                page.add_redact_annot(r, fill=(0,0,0))
        try:
            page.apply_redactions()
        except Exception:
            pass
    meta = doc.metadata or {}
    for k in ['author','subject','creator','producer','keywords']:
        meta[k] = ''
    doc.set_metadata(meta)
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    doc.save(output_path, garbage=4, deflate=True, clean=True)
    doc.close()
    verify_redaction(input_path, output_path)
